#!/usr/bin/env python3
"""Harness helpers: parse the request dog sends so we can see what it parsed."""
import sys, os, struct
sys.path.insert(0,'/tmp/h')
from probe import run
from dnsbuild import *

TYPES = {1:'A',2:'NS',5:'CNAME',6:'SOA',12:'PTR',13:'HINFO',15:'MX',16:'TXT',24:'SIG',25:'KEY',28:'AAAA',29:'LOC',33:'SRV',35:'NAPTR',41:'OPT',44:'SSHFP',52:'TLSA',257:'CAA'}
CLASSES = {1:'IN',3:'CH',4:'HS',255:'ANY'}

def rdname(b, off):
    labs=[]
    while True:
        l=b[off]; off+=1
        if l==0: break
        if l>=0xc0:
            off+=1; labs.append('<ptr>'); break
        labs.append(b[off:off+l].decode('utf-8','replace')); off+=l
    return '.'.join(labs), off

def parse_req(b):
    if len(b) < 12: return {'raw':hexs(b)}
    txid, flags, qd, an, ns, ar = struct.unpack('!HHHHHH', b[:12])
    off=12; qs=[]
    for _ in range(qd):
        n, off = rdname(b, off)
        t, c = struct.unpack('!HH', b[off:off+4]); off+=4
        qs.append((n, TYPES.get(t, str(t)), CLASSES.get(c, str(c)), t, c))
    extra=[]
    for _ in range(ar):
        n, off = rdname(b, off)
        t, c, ttl, rl = struct.unpack('!HHIH', b[off:off+10]); off+=10
        rd=b[off:off+rl]; off+=rl
        extra.append((n or '.', TYPES.get(t,str(t)), c, ttl, hexs(rd)))
    return {'txid':'0x%04x'%txid, 'flags':'0x%04x'%flags, 'counts':(qd,an,ns,ar), 'q':qs, 'ar':extra}

def go(args, resp=None, count=1, srvcount=None, tcp=False, label=None, env=None, timeout=25, show_out=True):
    if resp is None:
        resp = lambda req, i: hdr(an=0, flags=0x8180) + req[12:]
    out, err, rc, reqs = run(args, resp, count=count, srvcount=srvcount, tcp=tcp, env=env, timeout=timeout)
    print('$ dog ' + ' '.join(args) + ((' # '+label) if label else ''))
    print('  RC=%s  nreq=%d' % (rc, len(reqs)))
    for i, r in enumerate(reqs):
        print('  REQ[%d]: %s' % (i, parse_req(r)))
    if show_out:
        print('  OUT=%r' % out)
        print('  ERR=%r' % err)
    return out, err, rc, reqs
EOF
